@php use App\Infrastructure\Docker\Yaml; @endphp
# Generated by Mini Forge. Changes here are overwritten on the next provisioning.
name: mini-forge

x-logging: &logging
  driver: local
  options:
    max-size: "10m"
    max-file: "3"

services:
  # Traefik reads container labels through this proxy instead of the raw
  # Docker socket. It only allows GET on containers, events, version and
  # ping, so Traefik cannot start, stop or exec into anything.
  socket-proxy:
    image: {!! Yaml::string($socketProxyImage) !!}
    container_name: mini-forge-socket-proxy
    restart: unless-stopped
    environment:
      CONTAINERS: "1"
      EVENTS: "1"
      PING: "1"
      VERSION: "1"
      POST: "0"
    volumes:
      - /var/run/docker.sock:/var/run/docker.sock:ro
    networks: [socket]
    mem_limit: 64m
    logging: *logging

  traefik:
    image: {!! Yaml::string($traefikImage) !!}
    container_name: mini-forge-traefik
    restart: unless-stopped
    depends_on: [socket-proxy]
    command:
      - --providers.docker.endpoint=tcp://socket-proxy:2375
      # Only containers with traefik.enable=true are routed.
      - --providers.docker.exposedbydefault=false
      - {!! Yaml::string('--providers.docker.network='.$network) !!}
      - --entrypoints.web.address=:80
      - --entrypoints.web.http.redirections.entrypoint.to=websecure
      - --entrypoints.web.http.redirections.entrypoint.scheme=https
      - --entrypoints.websecure.address=:443
      - --entrypoints.websecure.http.tls.certresolver=letsencrypt
      - --entrypoints.websecure.http3=true
      - {!! Yaml::string('--certificatesresolvers.letsencrypt.acme.email='.$acmeEmail) !!}
      - --certificatesresolvers.letsencrypt.acme.storage=/letsencrypt/acme.json
      - --certificatesresolvers.letsencrypt.acme.httpchallenge.entrypoint=web
      # The dashboard and API stay off; ping serves the health check on the
      # internal port 8080, which is not published.
      - --api.dashboard=false
      - --ping=true
      - --log.level=WARN
    ports:
      - "80:80"
      - "443:443"
      - "443:443/udp"
    volumes:
      - letsencrypt:/letsencrypt
    networks: [socket, proxy]
    healthcheck:
      test: ["CMD", "traefik", "healthcheck", "--ping"]
      interval: 10s
      timeout: 5s
      retries: 3
      start_period: 10s
    mem_limit: 256m
    logging: *logging

  # Shared by all sites, one database and login role per site. Reachable
  # only on the internal data network; never published on the host.
  postgres:
    image: {!! Yaml::string($postgresImage) !!}
    container_name: mini-forge-postgres
    restart: unless-stopped
    env_file: .env
    # Sized for a small (1-2 GB) server.
    command:
      - postgres
      - -c
      - shared_buffers=128MB
      - -c
      - effective_cache_size=256MB
      - -c
      - work_mem=4MB
      - -c
      - maintenance_work_mem=32MB
      - -c
      - max_connections=60
    volumes:
      - postgres:/var/lib/postgresql/data
    networks:
      data:
        aliases: [postgres]
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U postgres"]
      interval: 10s
      timeout: 5s
      retries: 5
    logging: *logging

  # One logical database and ACL user per site (see redis/users.acl).
  redis:
    image: {!! Yaml::string($redisImage) !!}
    container_name: mini-forge-redis
    restart: unless-stopped
    env_file: .env
    command:
      - redis-server
      - --aclfile
      - /etc/redis-acl/users.acl
      - --appendonly
      - "yes"
      - --databases
      - "{{ $redisDatabases }}"
      - --maxmemory
      - 96mb
      - --maxmemory-policy
      - noeviction
    volumes:
      - ./redis:/etc/redis-acl
      - redis:/data
    networks:
      data:
        aliases: [redis]
    healthcheck:
      test: ["CMD-SHELL", "REDISCLI_AUTH=\"$$REDIS_PASSWORD\" redis-cli ping | grep -q PONG"]
      interval: 10s
      timeout: 5s
      retries: 5
    logging: *logging

networks:
  socket:
    internal: true
  proxy:
    name: {!! Yaml::string($network) !!}
    external: true
  data:
    name: {!! Yaml::string($dataNetwork) !!}
    external: true

volumes:
  letsencrypt:
  postgres:
  redis:
